function stxGBExpansionCatchup(e,rules,worldCount){if(!e||e.id===0)return rules;const alive=state.empires.filter(x=>stxGBAlive(x.id)),counts=alive.map(x=>owned(x.id).length).sort((a,b)=>a-b),median=counts[Math.floor(counts.length/2)]||worldCount,neutral=state.planets.filter(p=>p.owner===null).length,lag=Math.max(0,median-worldCount),stalled=Math.max(0,state.simTime-(e.lastExpansion||0)),pressure=neutral>16?2:neutral>7?1:0;return{...rules,maxWorlds:Math.max(rules.maxWorlds,worldCount+lag+pressure,Math.min(12,3+Math.floor(state.simTime/190))),cooldown:Math.max(22,rules.cooldown*(lag?Math.max(.62,1-lag*.11):stalled>190&&neutral? .72:1)),intent:clamp(rules.intent+lag*.1+(stalled>180&&neutral?.12:0),.06,.98)}}
if(typeof stxRDExpansionRules==="function"){
  const STX_GB_expansionRules=stxRDExpansionRules;stxRDExpansionRules=function(e,worldCount=owned(e.id).length){return stxGBExpansionCatchup(e,STX_GB_expansionRules(e,worldCount),worldCount)};
}

function stxGBAllAgreements(){state.rivalDiplomacy=state.rivalDiplomacy||{agreements:[]};state.rivalDiplomacy.agreements=Array.isArray(state.rivalDiplomacy.agreements)?state.rivalDiplomacy.agreements:[];return state.rivalDiplomacy.agreements}
