function stxGBAddAgreement(kind,a,b,duration=170,extra={}){const existing=stxGBAgreement(kind,a,b);if(existing)return existing;const record=typeof stxRDAddAgreement==="function"?stxRDAddAgreement(kind,a,b,duration,extra):{id:stxGBId("gba"),kind,by:a,with:b,createdAt:state.simTime,expiresAt:state.simTime+duration,active:true,...extra};return record}
function stxGBEmbargoesAgainst(owner){return stxGBAllAgreements().filter(x=>x.active!==false&&x.kind==="embargo"&&x.with===owner&&x.by!==owner&&x.expiresAt>state.simTime)}
function stxGBEmbargoRoute(embargo){
  const by=owned(embargo.by),against=owned(embargo.with);if(!by.length||!against.length)return null;let from=null,to=null,best=Infinity;by.forEach(a=>against.forEach(b=>{const d=dist(a,b);if(d<best){best=d;from=a;to=b}}));if(!from||!to)return null;const t=.58;return{from,to,x:from.x+(to.x-from.x)*t,y:from.y+(to.y-from.y)*t,distance:best};
}
function stxGBEmbargoStrength(by,against){const fleets=state.fleets.filter(f=>f.owner===by&&!f.destroyed).sort((a,b)=>(b.strength||0)-(a.strength||0)),fleetIds=fleets.slice(0,2).map(f=>f.id),strength=Math.max(9,fleets.slice(0,2).reduce((n,f)=>n+(f.strength||0)*.3,0)+empireIndustry(by)*1.5);return{strength,fleetIds}}
