function stxGBRelationStatus(a,b){if(getWar(a,b))return"At War";if(stxGBAgreement("mutual-defense",a,b))return"Allied";const rel=relation(a,b),pair=typeof stxRDPair==="function"?stxRDPair(a,b):null,tension=pair?.tension||0;if(rel>.5&&tension<34)return"Friendly";if(rel>-.08&&tension<48)return"Neutral";if(rel>-.38&&tension<70)return"Suspicious";return"Hostile"}
