simulate=function(dt){const result=STX_GB_simulate(dt);stxGBTtickEmbargoBattles(dt);stxGBStrategicTick();return result};

function stxGBEmbargoCard(e){const route=stxGBEmbargoRoute(e);return`<article class="transmission-card urgent stx-gb-embargo"><div class="card-kicker">ACTIVE EMBARGO // ${stxGBEscape(empire(e.by)?.name)}</div><div class="card-title"><strong>Trade lanes under interdiction</strong><span class="news-time">${fmtEta(e.expiresAt-state.simTime)}</span></div><p class="card-copy">${stxGBEscape(e.reason||"Strategic pressure")} · approximately ${Math.round(e.strength||0)} enforcement strength is visible along ${stxGBEscape(route?.to?.name||"Mandate frontier")} routes.</p><div class="choice-row"><span class="stx-gb-warning">BREAK EMBARGO appears as an additional command option. Attacking declares war.</span></div></article>`}
function stxGBFlagshipPrompt(){if(!stxGBFlagshipEligible(0)||stxGBFlagshipFleet(0))return"";return`<article class="transmission-card governor stx-gb-flagship-prompt"><div class="card-kicker">ADMIRALTY // PRESTIGE COMMAND</div><div class="card-title"><strong>Designate the Imperial Flagship</strong></div><p class="card-copy">Fleet Power has reached 100. Select one active formation in Famous Fleets; only one flagship may serve at a time.</p><div class="choice-row"><button class="choice-btn primary-choice" id="stxGBOpenFleets">Open Famous Fleets</button></div></article>`}
const STX_GB_renderTransmissions=renderTransmissions;
renderTransmissions=function(){STX_GB_renderTransmissions();const box=$("transmissionList");if(!box)return;const embargoes=stxGBEmbargoesAgainst(0).filter(e=>!getWar(0,e.by));const html=embargoes.map(stxGBEmbargoCard).join("")+stxGBFlagshipPrompt();if(html)box.insertAdjacentHTML("beforeend",html);const open=$("stxGBOpenFleets");if(open)open.onclick=()=>switchHubTab("fleets")};

function stxGBDecorateFleetRegistry(){const box=$("fleetGrid");if(!box)return;const fleets=state.fleets.slice().sort((a,b)=>Number(a.destroyed)-Number(b.destroyed)||b.victories-a.victories||b.battles-a.battles),cards=[...box.querySelectorAll?.(".fleet-card")||[]],current=stxGBFlagshipFleet(0),eligible=stxGBFlagshipEligible(0);cards.forEach((card,i)=>{const f=fleets[i];if(!f)return;if(f.isFlagship){card.classList.add("stx-gb-flagship-card");card.insertAdjacentHTML("afterbegin",`<div class="stx-gb-flagship-banner">✦ FLAGSHIP ${stxGBEscape(f.flagshipName)} · +${Math.round((f.flagshipBonus||.08)*100)}% COMBAT PRESTIGE</div>`)}else if(f.owner===0&&!f.destroyed&&eligible&&!current)card.insertAdjacentHTML("beforeend",`<button class="choice-btn stx-gb-designate" data-stx-flagship="${f.id}">Designate as Flagship</button>`)});box.querySelectorAll?.("[data-stx-flagship]").forEach(b=>b.onclick=()=>{if(stxGBDesignateFlagship(0,b.dataset.stxFlagship)){renderFleetRegistry();renderTransmissions();updateHud(true)}})}
const STX_GB_renderFleetRegistry=renderFleetRegistry;
renderFleetRegistry=function(){STX_GB_renderFleetRegistry();stxGBDecorateFleetRegistry()};

function stxGBCoalitionSummary(){const active=state.galacticBalance?.coalitions?.filter(c=>c.status==="active")||[];if(!active.length)return"";return`<div class="stx-gb-coalitions">${active.map(c=>`<span><b>${stxGBEscape(c.name)}</b>${stxGBEscape(c.posture)} · ${c.members.map(id=>stxGBEscape(empire(id)?.name)).join(" + ")}</span>`).join("")}</div>`}
function stxGBDecorateRivals(){const grid=$("rivalGrid");if(!grid)return;const rivals=state.empires.filter(e=>e.id!==0&&stxGBAlive(e.id)),cards=[...grid.querySelectorAll?.(".rival-card")||[]];cards.forEach((card,i)=>{const e=rivals[i];if(!e)return;const assessment=stxGBThreatAssessment(e.id,0),ourView=stxGBThreatAssessment(0,e.id),coalition=stxGBActiveCoalition(0),member=coalition?.members.includes(e.id),embargo=stxGBEmbargoesAgainst(0).find(x=>x.by===e.id);card.insertAdjacentHTML("beforeend",`<div class="stx-gb-balance"><span><label>Their view of us</label><b>${stxGBEscape(assessment.level)}</b></span><span><label>Our view of them</label><b>${stxGBEscape(ourView.level)}</b></span><span><label>AI relationship</label><b>${stxGBEscape(stxGBRelationStatus(0,e.id))}</b></span><span><label>Military target</label><b>${Math.round(e.stxMilitaryTarget||stxGBMilitaryTarget(e.id))}</b></span>${member?'<em>ANTI-HEGEMONY COALITION MEMBER</em>':""}${embargo?'<em class="hostile">EMBARGO ENFORCER</em>':""}</div>`)});const summary=$("warSummary");if(summary)summary.insertAdjacentHTML("beforeend",stxGBCoalitionSummary())}
const STX_GB_renderRivals=renderRivals;
// Rendering must never remove empire identities used by fleet history and trade.
renderRivals=function(){
  if(state.stxSelectedRivalId!=null&&!stxGBAlive(state.stxSelectedRivalId))state.stxSelectedRivalId=state.empires.find(e=>e.id!==0&&stxGBAlive(e.id))?.id??null;
  STX_GB_renderRivals();stxGBDecorateRivals();
};

function stxGBDrawEmbargoes(){const t=performance.now()/1000;ctx.save();stxGBAllAgreements().filter(e=>e.active!==false&&e.kind==="embargo"&&e.expiresAt>state.simTime).forEach(e=>{const route=stxGBEmbargoRoute(e);if(!route||(!visible(route.from.x,route.from.y,240)&&!visible(route.to.x,route.to.y,240)))return;const a=worldToScreen(route.from.x,route.from.y),b=worldToScreen(route.to.x,route.to.y);ctx.strokeStyle="rgba(255,104,57,.62)";ctx.lineWidth=2;ctx.setLineDash([9,6,2,6]);ctx.lineDashOffset=-(t*18)%23;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);for(let i=0;i<3;i++){const phase=(t*.055+i/3)%1,x=a.x+(b.x-a.x)*phase,y=a.y+(b.y-a.y)*phase,angle=Math.atan2(b.y-a.y,b.x-a.x);ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle="#ff8d55";ctx.shadowColor="#ff5c42";ctx.shadowBlur=9;ctx.beginPath();ctx.moveTo(7,0);ctx.lineTo(-4,-3);ctx.lineTo(-2,0);ctx.lineTo(-4,3);ctx.closePath();ctx.fill();ctx.restore()}if(state.camera.zoom>.5){ctx.fillStyle="#ff9b64";ctx.font="800 8px system-ui";ctx.textAlign="center";ctx.fillText(`EMBARGO · ${empire(e.by)?.name||"Unknown"}`, (a.x+b.x)/2,(a.y+b.y)/2-9)}});ctx.restore()}
const STX_GB_drawTradeCorridors=drawTradeCorridors;
drawTradeCorridors=function(){STX_GB_drawTradeCorridors();stxGBDrawEmbargoes()};
function stxGBFlagshipPoint(f){const ship=state.ships.find(s=>s.fleetId===f.id);if(ship)return ship;if(f.deepSpaceBaseId&&typeof stxDSBase==="function")return stxDSBase(f.deepSpaceBaseId);return state.planets.find(p=>p.id===f.location)||state.planets.find(p=>p.id===f.homePort)||null}
function stxGBDrawFlagships(){const t=performance.now()/1000;state.fleets.filter(f=>f.isFlagship&&!f.destroyed).forEach(f=>{const p=stxGBFlagshipPoint(f);if(!p||!visible(p.x,p.y,80))return;const s=worldToScreen(p.x,p.y),r=clamp(17*state.camera.zoom,10,26),color=empire(f.owner)?.color||"#fff";ctx.save();ctx.translate(s.x,s.y);ctx.rotate(t*.22);ctx.strokeStyle="#ffe48b";ctx.shadowColor=color;ctx.shadowBlur=14;ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(0,-r);ctx.lineTo(r*.58,0);ctx.lineTo(0,r);ctx.lineTo(-r*.58,0);ctx.closePath();ctx.stroke();ctx.rotate(-t*.44);ctx.setLineDash([3,5]);ctx.beginPath();ctx.arc(0,0,r*1.35,0,6.283);ctx.stroke();ctx.restore();if(state.camera.zoom>.58){ctx.fillStyle="#ffe9a4";ctx.font="900 8px system-ui";ctx.textAlign="center";ctx.fillText(`FLAGSHIP · ${f.flagshipName}`,s.x,s.y-r*1.7)}})}
function stxGBDrawEmbargoBattles(){const t=performance.now()/1000;state.galacticBalance.embargoBattles.filter(b=>b.active).forEach(b=>{if(!visible(b.x,b.y,140))return;const s=worldToScreen(b.x,b.y),r=clamp(68*state.camera.zoom,32,90),ac=empire(b.owner)?.color||"#6cf",dc=empire(b.defender)?.color||"#f65";ctx.save();ctx.globalCompositeOperation="lighter";for(let i=0;i<7;i++){const a=t*(i%2?-.7:.72)+i*.9,p={x:s.x+Math.cos(a)*r,y:s.y+Math.sin(a)*r*.48},q={x:s.x-Math.cos(a)*r*.65,y:s.y-Math.sin(a)*r*.34};drawCombatCraft(p,q,i%2?ac:dc,3,i===0)}ctx.strokeStyle="#ff864e";ctx.setLineDash([5,5]);ctx.beginPath();ctx.arc(s.x,s.y,r+9,0,6.283);ctx.stroke();ctx.restore()})}
const STX_GB_draw=draw;
draw=function(){STX_GB_draw();stxGBDrawFlagships();stxGBDrawEmbargoBattles()};

function stxGBInstallStyles(){if($("stxGBStyles"))return;const style=document.createElement("style");style.id="stxGBStyles";style.textContent=`
.command-card.stx-gb-break-embargo{grid-column:1/-1;border-color:rgba(255,86,57,.72)!important;background:linear-gradient(135deg,rgba(255,72,47,.2),rgba(75,10,24,.6))!important;box-shadow:0 0 22px rgba(255,72,47,.12)}.command-card.stx-gb-break-embargo h3{color:#ffb19d}.stx-gb-warning{padding:7px 9px;border:1px solid rgba(255,88,59,.38);border-radius:8px;background:rgba(255,70,45,.09);color:#ffb29f;font-size:.61rem;font-weight:900}.stx-gb-flagship-card{border-color:rgba(255,225,126,.55)!important;box-shadow:0 0 18px rgba(255,213,95,.09)}.stx-gb-flagship-banner{margin:-13px -13px 11px;padding:7px 10px;background:linear-gradient(90deg,rgba(255,211,91,.18),rgba(111,87,255,.12));border-bottom:1px solid rgba(255,225,126,.28);color:#ffe9a5;font-size:.55rem;font-weight:950;letter-spacing:.1em}.stx-gb-designate{margin-top:9px;width:100%;border-color:rgba(255,221,119,.42)!important;color:#ffe39a}.stx-gb-balance{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin:9px 0 0;padding-top:8px;border-top:1px solid rgba(255,255,255,.07)}.stx-gb-balance>span{padding:6px;border-radius:7px;background:rgba(5,12,28,.55)}.stx-gb-balance label,.stx-gb-balance b{display:block}.stx-gb-balance label{font-size:.46rem;color:#7287a1;text-transform:uppercase}.stx-gb-balance b{margin-top:2px;font-size:.58rem;color:#edf6ff}.stx-gb-balance em{grid-column:1/-1;padding:5px 7px;border-radius:6px;background:rgba(255,177,68,.09);color:#ffc46f;font-size:.49rem;font-style:normal;font-weight:950;letter-spacing:.06em}.stx-gb-balance em.hostile{background:rgba(255,78,76,.1);color:#ff9e92}.stx-gb-coalitions{display:grid;gap:5px;margin-top:7px}.stx-gb-coalitions span{display:block;padding:8px;border:1px solid rgba(255,181,73,.22);border-radius:8px;background:rgba(255,173,61,.06);font-size:.58rem;color:#9fb0c6}.stx-gb-coalitions b{display:block;color:#ffc66e;font-size:.64rem}.stx-gb-embargo{border-color:rgba(255,91,63,.42)!important}
`;document.head.appendChild(style)}

globalThis.SpaceTyrantsGalacticBalance={version:STX_GB_VERSION,ensureState:stxGBEnsureState,power:stxGBPower,militaryTarget:stxGBMilitaryTarget,threat:stxGBThreatAssessment,threatLevel:stxGBThreatLevel,relationStatus:stxGBRelationStatus,imposeEmbargo:stxGBImposeEmbargo,embargoesAgainst:stxGBEmbargoesAgainst,respondToEmbargo:stxGBAIEmbargoResponses,formCoalition:stxGBFormCoalition,activeCoalition:stxGBActiveCoalition,designateFlagship:stxGBDesignateFlagship,flagship:stxGBFlagshipFleet,eliminateEmpire:stxGBEliminateEmpire,expansionCatchup:stxGBExpansionCatchup,recordAggression:stxGBRecordAggression};
stxGBEnsureState(false);stxGBNormalizeEmbargoes();stxGBInstallStyles();stxGBCleanupEliminated();
